from openpyxl import Workbook
from openpyxl.styles import Font,Alignment,PatternFill
wb=Workbook();ws=wb.active;ws.title='Recommended 10'
def sheet(ws,cols,rows,widths):
    ws.append(cols)
    for r in rows: ws.append(list(r))
    for c in ws[1]: c.font=Font(bold=True,color='FFFFFF');c.fill=PatternFill('solid',fgColor='1F3864');c.alignment=Alignment(wrap_text=True,vertical='top')
    for row in ws.iter_rows(min_row=2):
        for c in row: c.alignment=Alignment(wrap_text=True,vertical='top')
    for i,wd in enumerate(widths): ws.column_dimensions[chr(65+i)].width=wd
    ws.freeze_panes='A2'
